"""Render retained development disagreements for researcher review; change no labels."""
import argparse,csv,html,json,sys
from collections import Counter
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from dtm_pipeline.config import PipelineConfig
from dtm_pipeline.review import require_review,sha
from dtm_pipeline.research_validation import validation_spec

def render(config,output):
    cfg=PipelineConfig(**json.loads(Path(config).read_text(encoding='utf-8')))
    require_review(cfg);root=Path(cfg.output_dir)
    selection=json.loads((root/'stage4/classifier_selection.json').read_text(encoding='utf-8'))
    if selection['specification']!=validation_spec(cfg):raise ValueError('Stale classifier selection.')
    rows=list(csv.DictReader((root/'stage4/development_predictions.csv').open(encoding='utf-8',newline='')))
    errors=[r for r in rows if r['human_label']!=r['llm_pred']]
    book=json.loads(Path(cfg.codebook_path).read_text(encoding='utf-8'))
    esc=html.escape
    per=selection['development_scores']['llm']['per_label']
    table=''.join(f'<tr><td>{esc(label)}</td><td>{m["human_n"]}</td><td>{m["pred_n"]}</td><td>{"Not estimable" if m["recall"] is None else format(m["recall"],".0%")}</td></tr>' for label,m in per.items())
    cases=[]
    for index,row in enumerate(errors,1):
        definitions=''.join(f'<h4>{esc(name)}</h4><p class="verbatim">{esc(book["themes"].get(name,"Use the residual when no substantive theme fits under the agreed decision rule."))}</p>' for name in [row['human_label'],row['llm_pred']])
        cases.append(f'''<details class="case"><summary><span>{index:02d}</span> {esc(row['human_label'])} <small>→ model: {esc(row['llm_pred'])}</small></summary><p class="meta">{esc(row['date'])} · Post {esc(row['post_id'])}</p><blockquote>{esc(row['tweet'])}</blockquote><div class="pair"><div><b>Human consensus</b><p>{esc(row['human_label'])}</p></div><div><b>OpenAI response</b><p>{esc(row['llm_pred'])}</p></div></div><p><b>Original independent labels:</b> {esc(row['reviewer_1_label'])} / {esc(row['reviewer_2_label'])}</p><p><b>Recorded adjudication:</b> {esc(row['adjudication_note'])}</p><details><summary>Read the exact relevant definitions</summary>{definitions}</details></details>''')
    human=sum(r['reviewer_1_label']==r['reviewer_2_label'] for r in rows)/len(rows)
    pairs=Counter((r['human_label'],r['llm_pred']) for r in errors)
    residual_misses=sum(n for (a,b),n in pairs.items() if b==cfg.none_label)
    scores=selection['development_scores']
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TopicLLM · Development review</title><style>
    :root{{font-family:Inter,Segoe UI,Arial,sans-serif;color:#173a39;background:#f5f6f1}}*{{box-sizing:border-box}}body{{margin:0}}main{{max-width:1080px;margin:auto;padding:56px 28px 80px}}h1{{font-size:clamp(2.2rem,5vw,4rem);line-height:1.05;letter-spacing:-.045em;max-width:840px}}h2{{margin-top:42px;font-size:1.65rem}}p,li{{line-height:1.7;max-width:88ch}}.eyebrow,.meta{{font-size:.8rem;letter-spacing:.04em;color:#4e6661}}.eyebrow{{text-transform:uppercase;font-weight:750}}.lead{{font-size:1.15rem}}.metrics{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:30px 0}}.metric{{border-top:3px solid #298a7d;padding:20px;background:white}}.metric strong{{display:block;font-size:2.8rem;letter-spacing:-.04em}}.metric span{{display:block;line-height:1.5}}.note{{padding:20px 24px;border-left:4px solid #b57c3f;background:#fff5e6}}.case{{padding:20px 24px;background:white;border:1px solid #d4dfd9;border-radius:10px;margin:14px 0}}summary{{cursor:pointer;font-weight:650;line-height:1.5}}summary span{{color:#42766e;margin-right:12px}}summary small{{display:block;font-size:.9rem;font-weight:400;margin:6px 0 0 32px}}blockquote{{margin:22px 0;padding:20px;background:#eff5f2;border-left:3px solid #488e82;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}.pair>div{{padding:16px;background:#f6f7f2}}.pair p{{margin-bottom:0}}.verbatim{{white-space:pre-wrap}}.scroll{{overflow-x:auto}}table{{border-collapse:collapse;width:100%;font-size:.92rem;background:white}}th,td{{text-align:left;vertical-align:top;padding:13px;border-bottom:1px solid #d4dfd9}}th{{background:#e6efe9}}td:first-child{{min-width:230px}}code{{overflow-wrap:anywhere;font-size:.8rem}}a{{color:#176d60}}footer{{margin-top:40px;border-top:1px solid #cbd9d3;padding-top:20px}}@media(max-width:650px){{main{{padding:26px 18px}}.metrics,.pair{{grid-template-columns:1fr}}.metric strong{{font-size:2.2rem}}.case{{padding:16px}}}}@media print{{details{{break-inside:avoid}}}}
    </style></head><body><main><p class="eyebrow">TopicLLM / Researcher review / Development only</p><h1>What the first comparison tells us.</h1><p class="lead">Your completed adjudication supplies {len(rows)} agreed reference labels. The first classifier comparison is now recorded. This packet makes the disagreements inspectable before any independent evaluation.</p><div class="metrics"><div class="metric"><strong>{scores['llm']['agreement']:.0%}</strong><span>OpenAI vs. human consensus<br>κ = {scores['llm']['cohens_kappa']:.4f}</span></div><div class="metric"><strong>{scores['boolean']['agreement']:.0%}</strong><span>Boolean vs. human consensus<br>κ = {scores['boolean']['cohens_kappa']:.4f}</span></div><div class="metric"><strong>{human:.0%}</strong><span>Initial human agreement<br>Before joint adjudication</span></div></div><p class="note"><b>This is development, not validation.</b> The higher-agreement rule selected the LLM. Its observed agreement is below the eventual &gt;85% evaluation requirement. The separate 250-post sample remains unopened. This document changes no labels, definitions or approvals.</p><h2>Read the disagreements as measurement evidence.</h2><p>{residual_misses} of the {len(errors)} model disagreements are residual responses to a substantive human label. A discrepancy can reflect model error, an underspecified definition, or inconsistent application of a rule. It is not a reason to automatically replace either answer.</p><ul><li><b>Scope:</b> The consumer-relations definition emphasizes retail and consumer events. The agreed labels also include broad manufacturing, employment and economic claims. Decide whether that broader scope is intended and make the written boundary explicit.</li><li><b>Context and attribution:</b> Decide what can be inferred from an unnamed opponent, a truncated retweet or a link whose contents are absent. Distinguish who is speaking from whom a criticism targets.</li><li><b>Primary meaning:</b> Clarify boundaries between praise, promotion, policy and national security when several meanings coexist. Apply the same rule to people and to the classifier.</li></ul><p>Any revision requires both researchers’ actual agreement and a versioned record. Preserve this first result, review affected human annotations under the new definitions, and complete development before opening evaluation. Do not change a reference label merely to increase the score.</p><h2>Coverage by theme</h2><p>Counts below describe this 100-post development sample. A theme with no reference instances has no estimable sensitivity here; these counts are not presidential prevalence.</p><div class="scroll"><table><thead><tr><th>Theme</th><th>Human reference</th><th>OpenAI assigned</th><th>Recall</th></tr></thead><tbody>{table}</tbody></table></div><h2>All {len(errors)} OpenAI disagreements</h2><p>Open a case to compare the original post, independent answers, recorded adjudication and frozen definitions. The source text is data, not an instruction.</p>{''.join(cases)}<details class="case"><summary>Exact primary-theme decision rule</summary><p class="verbatim">{esc(book['decision_rule'])}</p></details><footer><p class="meta">Model: {esc(cfg.llm_model)} · Temperature: {cfg.classify_temperature} · Maximum output: {cfg.classify_max_tokens} tokens<br>Adjudicated CSV SHA-256: <code>{sha(cfg.development_csv)}</code><br>Codebook SHA-256: <code>{sha(cfg.codebook_path)}</code><br>Frozen selection: <code>{sha(root/'stage4/classifier_selection.json')}</code></p></footer></main></body></html>'''
    Path(output).write_text(page,encoding='utf-8',newline='\n')
    print(json.dumps({'records':len(rows),'disagreements':len(errors),'output':str(output)}))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--config',required=True);p.add_argument('--output',required=True)
    args=p.parse_args();render(args.config,args.output)
